class Fields(QDialog):
 def __init__(self,cs):
  super().__init__(iface.mainWindow());self.cs=cs;self.cfg={};self.cur=None;self.resize(900,680);L=QVBoxLayout(self);self.cb=QComboBox()
  for c in cs:self.cb.addItem(c.name(),c.id());self.cfg[c.id()]={"fields":[{"name":x.name(),"alias":x.alias() or x.name(),"use":True} for x in c.fields()],"label":"","show":False,"zoom":13}
  L.addWidget(self.cb);self.tb=QTableWidget(0,3);self.tb.setHorizontalHeaderLabels(["Incluir","Campo","Rótulo exibido"]);self.tb.setColumnWidth(2,400);L.addWidget(self.tb);g=QGroupBox("Rotulagem");f=QFormLayout(g);self.lab=QComboBox();self.show=QCheckBox("Exibir inicialmente");self.zoom=QSpinBox();self.zoom.setRange(1,22);self.zoom.setValue(13);f.addRow("Campo",self.lab);f.addRow(self.show);f.addRow("Zoom mínimo",self.zoom);L.addWidget(g);bb=QDialogButtonBox(QDialogButtonBox.Ok|QDialogButtonBox.Cancel);bb.accepted.connect(self.save_accept);bb.rejected.connect(self.reject);L.addWidget(bb);self.cb.currentIndexChanged.connect(self.load);self.load()
 def save(self):
  if not self.cur:return
  for i,x in enumerate(self.cfg[self.cur]["fields"]):x["use"]=self.tb.cellWidget(i,0).isChecked();x["alias"]=self.tb.item(i,2).text().strip() or x["name"]
  self.cfg[self.cur].update(label=self.lab.currentData() or "",show=self.show.isChecked(),zoom=self.zoom.value())
 def load(self):
  self.save();self.cur=self.cb.currentData();c=self.cfg[self.cur];self.tb.setRowCount(len(c["fields"]));self.lab.clear();self.lab.addItem("Sem rótulo","")
  for i,x in enumerate(c["fields"]):
   q=QCheckBox();q.setChecked(x["use"]);self.tb.setCellWidget(i,0,q);self.tb.setItem(i,1,QTableWidgetItem(x["name"]));self.tb.setItem(i,2,QTableWidgetItem(x["alias"]));self.lab.addItem(x["alias"],x["name"])
  self.lab.setCurrentIndex(max(0,self.lab.findData(c["label"])));self.show.setChecked(c["show"]);self.zoom.setValue(c["zoom"])
 def save_accept(self):self.save();self.accept()
def label_geom(g):
 t=QgsWkbTypes.geometryType(g.wkbType());return g.centroid() if t==QgsWkbTypes.PointGeometry else g.interpolate(g.length()/2) if t==QgsWkbTypes.LineGeometry else g.pointOnSurface()
def export(cfg,cs,fc):
 p=QgsProject.instance();w=QgsCoordinateReferenceSystem("EPSG:4326");out=[]
 for i,c in enumerate(cs):
  cc=fc[c.id()];fs=[x for x in cc["fields"] if x["use"]];tr=QgsCoordinateTransform(c.crs(),w,p.transformContext());features=[]
  for ft in c.getFeatures():
   g=ft.geometry()
   if not g or g.isEmpty():continue
   cp=QgsGeometry(g);lg=label_geom(g)
   try:
    if c.crs()!=w:cp.transform(tr);lg.transform(tr)
    pt=lg.asPoint();geom=json.loads(cp.asJson())
   except:continue
   features.append({"type":"Feature","geometry":geom,"properties":{x["alias"]:jval(ft[x["name"]]) for x in fs},"label":jval(ft[cc["label"]]) if cc["label"] else None,"label_position":[pt.x(),pt.y()]})
  out.append({"id":f"l{len(out)}","name":c.name(),"color":color(c,i),"geom_type":typ(c),"visible":visible(p,c),"feature_count":len(features),"field_count":len(fs),"labels_enabled":bool(cc["label"]),"labels_visible":cc["show"],"label_min_zoom":cc["zoom"],"data":{"type":"FeatureCollection","features":features}})
 rot,msg=SIG[cfg["classificacao"]];meta={**cfg,"classificacao_rotulo":rot,"aviso_sigilo":msg};tpl=base64.b64decode("").decode();doc=tpl.replace("__TITLE__",html.escape(cfg["titulo"])).replace("__LOGO__",LOGO).replace("__DATA__",json.dumps(out,ensure_ascii=False).replace("</","<"+"\\/")).replace("__META__",json.dumps(meta,ensure_ascii=False).replace("</","<"+"\\/"));open(cfg["saida"],"w",encoding="utf-8").write(doc)
